<script setup lang="ts">
import AdminSidebarLinks from '../components/AdminSidebarLinks.vue'
import '../styles/fac-list.css'
import MenuIcon from './MenuIcon.vue'
import {ref,computed,watch} from 'vue'
import {useApp} from '../stores/app'
import {backend} from '../services/backend'
import {useRouter,useRoute} from 'vue-router'
const route=useRoute(),mobile=computed(()=>route.path.startsWith('/admin-app/'))
import AdminSidebarNav from './AdminSidebarNav.vue'
import AdminIdentity from './AdminIdentity.vue'
withDefaults(defineProps<{standardMenu?:boolean}>(),{standardMenu:false})
const app=useApp(),router=useRouter(),open=ref(false),error=ref('')
const navigating=ref(false)
watch(()=>route.fullPath,()=>{open.value=false})
async function navigateMenu(event:MouseEvent){
 const link=(event.target as Element).closest<HTMLAnchorElement>('a[href]')
 if(!link||event.button!==0||event.ctrlKey||event.metaKey||event.shiftKey||event.altKey||link.target==='_blank'||link.hasAttribute('download'))return
 const url=new URL(link.href,location.href)
 if(url.origin!==location.origin)return
 event.preventDefault()
 open.value=false
 if(navigating.value)return
 navigating.value=true;error.value=''
 try{await router.push(url.pathname+url.search+url.hash)}
 catch{error.value='페이지를 불러오지 못했습니다. 메뉴를 다시 선택해 주세요.'}
 finally{navigating.value=false}
}
async function logout(){try{await backend('/api/auth/logout',{method:'POST'});app.clearAccount();await router.push(mobile.value?'/admin-app/screen-1':'/admin-login')}catch(e){error.value=(e as Error).message}}
</script>
<template><div class="backend-layout wire-page page-fac-list restored-admin-layout"><template v-if="!mobile"><header class="hdr backend-header"><div class="hdr-l"><button class="iconbtn" type="button" aria-label="관리자 메뉴 열기" :aria-expanded="open" @click="open=!open"><MenuIcon/></button><RouterLink class="admin-home-logo" :to="mobile?'/admin-app/screen-3':'/admin-dashboard'">ROUTEL</RouterLink></div><div class="hdr-r"><RouterLink class="iconbtn" to="/notifications" aria-label="관리자 알림 내역"><svg viewBox="0 0 24 24" width="22" height="22" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.8"><path d="M6 17v-6a6 6 0 0 1 12 0v6l1.5 2h-15L6 17zM10 21h4" stroke-linejoin="round" stroke-linecap="round"/></svg></RouterLink><RouterLink class="user backend-user" to="/admin-profile">{{app.account?.name||'관리자'}}님</RouterLink><button class="btn sm" v-if="app.account" @click="logout">로그아웃</button><RouterLink v-else to="/admin-login">관리자 로그인</RouterLink></div></header><div v-if="open" class="backend-scrim scrim" @click="open=false"></div><aside v-if="open" @click.capture="navigateMenu" class="backend-menu side open" aria-label="관리자 메뉴"><div class="backend-menu-head side-top"><b>관리자 메뉴</b><button class="btn sm" @click="open=false">닫기</button></div><AdminIdentity/><AdminSidebarNav live/><AdminSidebarLinks/></aside></template><main :class="mobile?'app-service-content':'backend-main page'" :aria-busy="navigating"><p v-if="navigating" role="status">페이지를 이동하고 있습니다…</p><p v-if="error" role="alert">{{error}}</p><slot/></main></div></template>
<style>
