ay:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px}.service-form-fields label{display:flex;flex-direction:column;gap:6px;min-width:0}.service-form-fields input,.service-form-fields select,.service-form-fields textarea,.service-workspace input,.service-workspace select{min-width:0;max-width:100%;min-height:42px;padding:8px 10px;border:1px solid var(--line);border-radius:6px;background:var(--surface);color:inherit;font:inherit}.service-form-fields input[type=checkbox]{min-height:20px;width:20px}.service-form-fields textarea{min-height:120px}.service-form-fields .wide{grid-column:1/-1}.service-table-wrap{overflow-x:auto;border:1px solid var(--line);border-radius:8px}.service-table{width:100%;border-collapse:collapse;min-width:640px;text-align:left}.service-table td,.service-table th{padding:12px;border-bottom:1px solid var(--line);font-size:13px;vertical-align:top;overflow-wrap:anywhere}.service-table td{max-width:320px}.service-table td img{max-width:180px;max-height:120px}.service-table th{white-space:nowrap;background:var(--surface)}.service-pagination{display:flex;gap:12px;justify-content:center;align-items:center;flex-wrap:wrap;width:100%;margin-top:16px}.service-pagination>span{white-space:nowrap}.service-modal{position:fixed;inset:0;margin:auto;width:min(720px,calc(100vw - 32px));max-height:calc(100dvh - 32px);padding:24px;border:1px solid var(--line);border-radius:12px;background:var(--surface);color:var(--foreground);overflow:auto}.service-modal video{display:block;width:100%;max-height:60vh;object-fit:contain;background:#101820}.service-modal:not([open]){display:none}.service-modal::backdrop{background:#14283e66}.service-modal header,.service-modal footer{display:flex;justify-content:space-between;align-items:center;gap:12px;margin-bottom:20px}.service-modal footer{justify-content:flex-end;margin:20px 0 0}.service-modal h2{margin:0;font-size:20px}.service-modal button{padding:10px 16px;border:1px solid var(--line);background:var(--surface);color:inherit;border-radius:6px}.service-detail{display:grid;grid-template-columns:130px minmax(0,1fr);gap:12px}.service-detail dd{margin:0;overflow-wrap:anywhere;white-space:pre-wrap}.service-detail dt{color:#65748a}.service-workspace .service-filters{padding:16px;margin-bottom:20px;border:1px solid var(--line);border-radius:8px;display:flex;align-items:end;flex-wrap:wrap;gap:12px}.service-filters label{display:flex;flex-direction:column;gap:6px;max-width:240px;min-width:140px}.service-filters input[type=checkbox]{width:20px;min-height:20px}.service-readonly{color:#65748a;font-size:12px}.service-workspace :is(.service-heading,.service-actions,.service-filters) button{white-space:nowrap}@media(max-width:600px){.backend-main{padding:20px 12px}.backend-header{padding:12px;gap:10px}.backend-user{font-size:12px}.service-heading{align-items:flex-start;flex-direction:column}.service-form-fields{grid-template-columns:1fr}.service-filters label{flex:1;max-width:none;min-width:120px}.service-detail{grid-template-columns:90px minmax(0,1fr)}.service-modal{padding:16px}}
</style>
<style>.service-mobile{width:100%;max-width:430px;margin:0 auto;min-height:100dvh;background:var(--surface)}.service-mobile .backend-main{padding:16px 12px}.service-mobile .server-summary{grid-template-columns:repeat(2,minmax(0,1fr))}.service-mobile .server-main,.service-mobile .server-bottom{grid-template-columns:1fr}.service-mobile .server-map .page-c-live-map .map-columns{grid-template-columns:1fr}.service-mobile .service-form-fields{grid-template-columns:1fr}.service-mobile .backend-header{padding:10px;gap:8px}.service-mobile .backend-header button,.service-mobile .backend-header a{font-size:12px}</style>
